PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS businesses(id TEXT PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'BRL',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','manager','cashier','member')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS users_business ON users(business_id);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),email TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('manager','cashier','member')),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS customers_business ON customers(business_id,active);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),title TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('todo','doing','done')),assignee_id TEXT REFERENCES users(id),due_date TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS tasks_business ON tasks(business_id);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),sku TEXT NOT NULL,name TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),stock INTEGER NOT NULL CHECK(stock>=0),track_stock INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(business_id,sku));
CREATE TABLE IF NOT EXISTS shifts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),user_id TEXT NOT NULL REFERENCES users(id),opening_cents INTEGER NOT NULL CHECK(opening_cents>=0),opened_at TEXT NOT NULL,closed_at TEXT,declared_cents INTEGER,expected_cents INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_shift ON shifts(user_id) WHERE closed_at IS NULL;
CREATE INDEX IF NOT EXISTS shifts_business ON shifts(business_id,opened_at);
CREATE TABLE IF NOT EXISTS sales(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),user_id TEXT NOT NULL REFERENCES users(id),shift_id TEXT NOT NULL REFERENCES shifts(id),customer_id TEXT REFERENCES customers(id),subtotal_cents INTEGER NOT NULL,discount_cents INTEGER NOT NULL DEFAULT 0,total_cents INTEGER NOT NULL CHECK(total_cents>=0),payment_method TEXT NOT NULL CHECK(payment_method IN('cash','card','pix','other')),status TEXT NOT NULL DEFAULT 'completed' CHECK(status IN('completed','refunded')),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(business_id,idempotency_key));
CREATE INDEX IF NOT EXISTS sales_business ON sales(business_id,created_at);
CREATE TABLE IF NOT EXISTS sale_items(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),price_cents INTEGER NOT NULL CHECK(price_cents>=0),track_stock INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),sale_id TEXT NOT NULL UNIQUE REFERENCES sales(id),shift_id TEXT NOT NULL REFERENCES shifts(id),user_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,total_cents INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),product_id TEXT NOT NULL REFERENCES products(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS stock_business ON stock_movements(business_id,created_at);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),user_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_business ON audit(business_id,created_at);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),name TEXT NOT NULL,document TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS projects_business ON projects(business_id);
